const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
document.addEventListener('DOMContentLoaded',()=>{mountChrome();mountLoader();document.body.classList.remove('loading');const h=$('.site-header'),t=$('.menu-toggle'),p=$('.scroll-progress');const onScroll=()=>{h?.classList.toggle('scrolled',scrollY>18);if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=`${max?scrollY/max*100:0}%`}};addEventListener('scroll',onScroll,{passive:true});onScroll();t?.addEventListener('click',()=>{const open=h.classList.toggle('open');t.setAttribute('aria-expanded',String(open))});$$('.nav a').forEach(a=>a.addEventListener('click',()=>h?.classList.remove('open')));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(el=>io.observe(el));loadSettings();initField()});
function mountLoader(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const first=!sessionStorage.getItem('rs-visited');const loader=document.createElement('div');loader.className=`page-loader${first?'':' is-short'}`;loader.setAttribute('aria-hidden','true');loader.innerHTML='<div class="loader-inner"><div class="loader-brand"><strong>REALIZE SUMMIT.</strong><span>LOADING</span></div><div class="loader-track"><div class="loader-bar"></div></div><div class="loader-count">ASCEND / 2026</div></div>';document.body.append(loader);sessionStorage.setItem('rs-visited','1');setTimeout(()=>loader.classList.add('is-done'),first?2200:620);document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target==='_blank'||a.hasAttribute('download')||a.href.startsWith('mailto:')||a.origin!==location.origin||(a.pathname===location.pathname&&a.search===location.search))return;e.preventDefault();loader.classList.remove('is-done','is-short');loader.classList.add('is-exit');setTimeout(()=>location.href=a.href,560)})}
function mountChrome(){const page=document.body.dataset.page||'';const links=[['home','index.html','HOME'],['about','about.html','ABOUT'],['news','news.html','NEWS'],['members','members.html','MEMBERS'],['sponsors','sponsors.html','SPONSORS'],['contact','contact.html','CONTACT'],['shop','shop.html','SHOP']];const header=`<header class="site-header"><div class="scroll-progress"></div><div class="container header-inner"><a class="brand" href="index.html" aria-label="Realize Summit ホーム"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><button class="menu-toggle" aria-label="メニューを開く" aria-expanded="false"><span></span><span></span></button><nav class="nav" aria-label="メインナビゲーション">${links.map(([id,href,label])=>`<a href="${href}" ${page===id?'aria-current="page"':''} class="${id==='shop'?'shop-link':''}">${label}</a>`).join('')}</nav></div></header>`;const footer=`<footer class="site-footer"><div class="container"><div class="footer-main"><a class="brand" href="index.html"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><nav class="footer-links">${links.map(([,h,l])=>`<a href="${h}">${l}</a>`).join('')}</nav><div class="social-links"><a data-setting="x" href="#">X</a><a data-setting="youtube" href="#">YOUTUBE</a></div></div><div class="copyright"><span>© 2026 REALIZE SUMMIT.</span><span>ALL RIGHTS RESERVED.</span></div></div></footer>`;$('#site-header')?.replaceWith(document.createRange().createContextualFragment(header));$('#site-footer')?.replaceWith(document.createRange().createContextualFragment(footer))}
async function loadSettings(){try{const s=await fetch('data/settings.json').then(r=>r.json());$$('[data-setting]').forEach(el=>{const k=el.dataset.setting;if(s[k]){if(el.tagName==='A')el.href=s[k];else el.textContent=s[k]}})}catch{}}
function initField(){const c=$('#hero-canvas');if(!c||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const gl=c.getContext('webgl',{alpha:false,antialias:false,powerPreference:'low-power'});if(!gl)return;const vs='attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';const fs='precision mediump float;uniform vec2 r;uniform vec2 m;uniform float t;void main(){vec2 u=(gl_FragCoord.xy-.5*r)/r.y;float w1=sin(u.x*1.7+u.y*.9+t*.055);float w2=sin(u.x*.65-u.y*1.35-t*.04);float w3=sin((u.x+u.y)*.42+t*.025);float field=(w1+w2*.7+w3*.45)/2.15;float red=smoothstep(-.85,.9,field);float halo=exp(-1.35*dot(u-vec2(.42,.08),u-vec2(.42,.08)));float beam=pow(max(0.,1.-abs(u.x*.5+u.y*.8)),5.);float md=1.-smoothstep(.0,.9,distance(u,m));vec3 col=vec3(.012,.013,.015);col+=vec3(.30,.018,.028)*(red*.48+halo*.24);col+=vec3(.34,.36,.40)*beam*.055;col+=vec3(.11,.008,.014)*md*.2;float vign=1.-smoothstep(.55,1.35,length(u));col*=.62+.38*vign;gl_FragColor=vec4(col,1.);}';function sh(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);return s}const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);gl.useProgram(pr);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const p=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(p);gl.vertexAttribPointer(p,2,gl.FLOAT,false,0,0);const ur=gl.getUniformLocation(pr,'r'),um=gl.getUniformLocation(pr,'m'),ut=gl.getUniformLocation(pr,'t');let w=0,h=0,raf,mouse=[0,0],start=performance.now();function resize(){const d=Math.min(devicePixelRatio,innerWidth<700?1:1.5);w=c.width=Math.floor(c.clientWidth*d);h=c.height=Math.floor(c.clientHeight*d);gl.viewport(0,0,w,h)}function draw(now){gl.uniform2f(ur,w,h);gl.uniform2f(um,mouse[0],mouse[1]);gl.uniform1f(ut,(now-start)/1000);gl.drawArrays(gl.TRIANGLES,0,3);raf=requestAnimationFrame(draw)}addEventListener('resize',resize);addEventListener('pointermove',e=>{mouse=[(e.clientX-innerWidth/2)/innerHeight,(innerHeight/2-e.clientY)/innerHeight]},{passive:true});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(raf);if(!document.hidden)raf=requestAnimationFrame(draw)});resize();raf=requestAnimationFrame(draw)}
